{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_store_pre_baseline AS WITH alloc_ref_dates AS ( SELECT DISTINCT branch_code::VARCHAR AS branch_code, order_date, DATEADD(\'day\', -1, order_date) AS reference_date FROM snitch_db.maplemonk.fresh_actual_allocation ), sales_units AS ( SELECT ar.branch_code, ar.order_date, ms.category, COALESCE(UPPER(ms.style), \'SNITCH\') AS style, COALESCE(UPPER(ms.meta1), \'N/A\') AS meta1, COALESCE(UPPER(ms.meta2), \'N/A\') AS meta2, COALESCE(UPPER(ms.meta3), \'N/A\') AS meta3, SUM(CASE WHEN s.order_date > DATEADD(\'day\', -7, ar.reference_date) THEN COALESCE(s.SUBORDER_QUANTITY, 1) ELSE 0 END) AS units_7d, SUM(CASE WHEN s.order_date > DATEADD(\'day\', -15, ar.reference_date) THEN COALESCE(s.SUBORDER_QUANTITY, 1) ELSE 0 END) AS units_15d, SUM(CASE WHEN s.order_date > DATEADD(\'day\', -30, ar.reference_date) THEN COALESCE(s.SUBORDER_QUANTITY, 1) ELSE 0 END) AS units_30d FROM alloc_ref_dates ar INNER JOIN snitch_db.maplemonk.STORE_FACT_ITEMS_OFFLINE s ON s.branch_code::VARCHAR = ar.branch_code AND s.order_date > DATEADD(\'day\', -30, ar.reference_date) AND s.order_date <= ar.reference_date AND LOWER(s.order_status) LIKE \'%process%\' AND s.doc_prefix NOT IN (\'OMS\', \'QCOM\') AND s.sku_group NOT LIKE \'%CB%\' LEFT JOIN snitch_db.maplemonk.metafields_std ms ON UPPER(s.sku_group) = UPPER(ms.sku_group) WHERE ms.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), sales_mix AS ( SELECT *, ( (units_7d / NULLIF(SUM(units_7d) OVER (PARTITION BY branch_code, order_date), 0)) * 0.50 + (units_15d / NULLIF(SUM(units_15d) OVER (PARTITION BY branch_code, order_date), 0)) * 0.30 + (units_30d / NULLIF(SUM(units_30d) OVER (PARTITION BY branch_code, order_date), 0)) * 0.20 ) AS ideal_mix_pct FROM sales_units ), inv_mix AS ( SELECT ar.branch_code, ar.order_date, ms.category, COALESCE(UPPER(ms.style), \'SNITCH\') AS style, COALESCE(UPPER(ms.meta1), \'N/A\') AS meta1, COALESCE(UPPER(ms.meta2), \'N/A\') AS meta2, COALESCE(UPPER(ms.meta3), \'N/A\') AS meta3, SUM(COALESCE(r.INVENTORY, 0) + COALESCE(r.JIT_QTY, 0)) AS pre_inv_units FROM alloc_ref_dates ar INNER JOIN snitch_db.maplemonk.offline_master_Daily_Report_1 r ON r.BRANCH_CODE::VARCHAR = ar.branch_code AND r.DATE = ar.reference_date LEFT JOIN snitch_db.maplemonk.metafields_std ms ON UPPER(r.SKU_GROUP) = UPPER(ms.sku_group) WHERE ms.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), joined AS ( SELECT COALESCE(s.branch_code, i.branch_code) AS branch_code, COALESCE(s.order_date, i.order_date) AS order_date, COALESCE(s.category, i.category) AS category, COALESCE(s.style, i.style) AS style, COALESCE(s.meta1, i.meta1) AS meta1, COALESCE(s.meta2, i.meta2) AS meta2, COALESCE(s.meta3, i.meta3) AS meta3, COALESCE(s.ideal_mix_pct, 0) AS ideal_mix_pct, COALESCE(i.pre_inv_units, 0) AS pre_inv_units, COALESCE(i.pre_inv_units, 0) / NULLIF(SUM(i.pre_inv_units) OVER (PARTITION BY COALESCE(s.branch_code, i.branch_code), COALESCE(s.order_date, i.order_date)), 0) AS pre_inv_mix_pct FROM sales_mix s FULL OUTER JOIN inv_mix i ON s.branch_code = i.branch_code AND s.order_date = i.order_date AND s.category = i.category AND s.style = i.style AND s.meta1 = i.meta1 AND s.meta2 = i.meta2 AND s.meta3 = i.meta3 ) SELECT *, GREATEST(ideal_mix_pct - pre_inv_mix_pct, 0) AS pre_gap_pct FROM joined;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            